	r2 := e.IngestLine(`[{"name":"cpu","timestamp":1000,"value":1.0}]`, 2)
	if !r2.OK || r2.New != 0 || r2.Duplicate != 1 {
		t.Fatalf("1 vs 1.0 should be duplicate, got ok=%v new=%d dup=%d err=%q", r2.OK, r2.New, r2.Duplicate, r2.Error)
	}
