		t.Fatalf("output lines = %d, want 1", len(lines))
	}
	if !strings.Contains(lines[0], `"line":3`) {
		t.Fatalf("line number = %s, want line 3", lines[0])
	}
}

func TestIngestCLIParseError(t *testing.T) {
